describe('Focus Indicators Accessibility', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
  });

  it('should display visible focus indicator when tabbing through interactive elements', () => {
    // Get all interactive elements
    const interactiveSelectors = [
      'button',
      'a[href]',
      'input[type="text"]',
      'input[type="button"]',
      'input[type="checkbox"]',
      'input[type="radio"]',
      'select',
      'textarea',
      '[role="button"]',
      '[role="link"]',
      '[role="menuitem"]'
    ];

    interactiveSelectors.forEach((selector) => {
      cy.get(selector).each(($element) => {
        cy.wrap($element).focus();

        // Check that element has focus
        cy.wrap($element).should('have.focus');

        // Verify focus indicator is visible through computed styles
        cy.wrap($element).should(($el) => {
          const styles = window.getComputedStyle($el[0]);
          const outline = styles.outline;
          const boxShadow = styles.boxShadow;
          const border = styles.border;

          // At least one focus indicator should be present
          const hasFocusIndicator = 
            (outline && outline !== 'none' && outline !== 'rgba(0, 0, 0, 0) none 0px') ||
            (boxShadow && boxShadow !== 'none') ||
            (border && border !== 'none');

          expect(hasFocusIndicator).to.be.true;
        });
      });
    });
  });

  it('should maintain focus indicator visibility with sufficient contrast', () => {
    cy.get('button').first().focus();

    cy.get('button').first().should(($button) => {
      const styles = window.getComputedStyle($button[0]);
      const focusColor = styles.outlineColor || styles.borderColor;
      const backgroundColor = styles.backgroundColor;

      // Verify focus indicator exists
      expect(styles.outline).not.to.equal('none');

      // Verify focus indicator has a color value
      expect(focusColor).to.exist;
      expect(focusColor).not.to.equal('transparent');
      expect(focusColor).not.to.equal('rgba(0, 0, 0, 0)');
    });
  });

  it('should show focus indicator on custom interactive components with role attributes', () => {
    cy.get('[role="button"]').first().focus();

    cy.get('[role="button"]').first().should(($element) => {
      const styles = window.getComputedStyle($element[0]);
      const hasFocusStyle = 
        styles.outline !== 'none' ||
        styles.boxShadow !== 'none' ||
        styles.backgroundColor !== window.getComputedStyle($element[0]).backgroundColor;

      expect(hasFocusStyle).to.be.true;
    });
  });

  it('should not remove focus indicator on hover state', () => {
    cy.get('button').first().as('testButton');

    // Get initial focus styles
    cy.get('@testButton').focus();
    cy.get('@testButton').should(($button) => {
      const focusedStyles = window.getComputedStyle($button[0]);
      const focusOutline = focusedStyles.outline;
      expect(focusOutline).not.to.equal('none');
    });

    // Hover and verify focus indicator persists
    cy.get('@testButton').trigger('mouseover');
    cy.get('@testButton').should(($button) => {
      const hoveredStyles = window.getComputedStyle($button[0]);
      const focusOutline = hoveredStyles.outline;
      expect(focusOutline).not.to.equal('none');
    });
  });

  it('should provide focus indicator for form inputs', () => {
    const formInputSelectors = [
      'input[type="text"]',
      'input[type="email"]',
      'input[type="password"]',
      'textarea',
      'select'
    ];

    formInputSelectors.forEach((selector) => {
      cy.get(selector).first().focus();

      cy.get(selector).first().should(($input) => {
        const styles = window.getComputedStyle($input[0]);
        const hasFocusIndicator = 
          (styles.outline && styles.outline !== 'none') ||
          (styles.boxShadow && styles.boxShadow !== 'none') ||
          (styles.borderColor && styles.borderColor !== 'transparent');

        expect(hasFocusIndicator).to.be.true;
      });
    });
  });
});
